    user_id
    ,keyword
    ,search_mid
    ,user_intention
    ,image_url
    ,image_bounding_box
    ,algo_intent_search_txt
    ,last_md5
    ,last_box_xy
    ,last_keyword
FROM
    dws_user_keyword_${grass_region_without_quote};

