CREATE TEMPORARY VIEW dim_keyword_${grass_region_without_quote} AS
SELECT
    keyword
    ,level1_keyword_category
    ,keyword_cluster
FROM 
    srdi_mart.dim_sr_data_warehouse_keyword_di
WHERE 
    grass_region IN (${grass_region})
    AND local_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_keyword_${grass_region_without_quote} AS
SELECT
    keyword
    ,CASE
        WHEN keyword_cumulative_search_volume_percentile <= 0.2 THEN '0%-20%'
        WHEN keyword_cumulative_search_volume_percentile <= 0.5 THEN '20%-50%'
        WHEN keyword_cumulative_search_volume_percentile <= 0.8 THEN '50%-80%'
        WHEN keyword_cumulative_search_volume_percentile <= 1.0 THEN '80%-100%'
        ELSE NULL
    END AS keyword_type
FROM 
    srdi_mart.dws_sr_data_warehouse_search_keyword_level_metrics_30d
WHERE 
    grass_region IN (${grass_region})
    AND local_date = ${local_date}
    AND is_ads = '__ALL__'
    AND card_type = '__ALL__'
    AND time_range = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW audio_url_${grass_region_without_quote} AS
SELECT
    user_id
    ,audio_url
FROM
    srdi_mart.dws_sr_data_warehouse_voice_search_session_level_metrics_1d
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
GROUP BY
    1,2;

