INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_sqe_sample_user_keyword_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    a.user_id
    ,a.keyword
    ,keyword_type
    ,level1_keyword_category
    ,keyword_cluster
    ,exp_group_ids
    ,exp_type
    ,search_mid
    ,audio_url
    ,user_intention
    ,image_url
    ,image_bounding_box
    ,algo_intent_search_txt
    ,last_md5
    ,last_box_xy
    ,last_keyword
FROM 
    dws_user_keyword_deduplicated_${grass_region_without_quote} a
INNER JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
LEFT JOIN
    dim_keyword_${grass_region_without_quote} c
ON
    a.keyword = c.keyword 
LEFT JOIN
    dws_keyword_${grass_region_without_quote} d
ON
    a.keyword = d.keyword
LEFT JOIN
    audio_url_${grass_region_without_quote} e
ON
    a.user_id = e.user_id;
